package qynl.agent;
import java.io.IOException;import java.nio.file.*;import java.util.*;
public final class WorldMemory{private final Path file;private final Map<String,String> facts=new LinkedHashMap<>();public WorldMemory(Path root){file=root.resolve("qynl_memory.properties");load();}public synchronized void put(String k,String v){facts.put(k,v);save();}public synchronized String get(String k){return facts.get(k);}public synchronized Map<String,String> snapshot(){return Map.copyOf(facts);}private void load(){if(!Files.exists(file))return;try{for(String l:Files.readAllLines(file)){int i=l.indexOf('=');if(i>0)facts.put(l.substring(0,i),l.substring(i+1));}}catch(IOException ignored){}}private void save(){try{List<String> o=new ArrayList<>();facts.forEach((k,v)->o.add(k+"="+v.replace("\n"," ")));Files.write(file,o,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}catch(IOException ignored){}}}
